import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Map, Calendar, Rocket } from 'lucide-react';

export default function WelcomeModal() {
    const [isOpen, setIsOpen] = useState(false);

    useEffect(() => {
        const hasSeenWelcome = localStorage.getItem('seen_welcome_modal');
        if (!hasSeenWelcome) {
            const timer = setTimeout(() => setIsOpen(true), 500);
            return () => clearTimeout(timer);
        }
    }, []);

    const handleClose = () => {
        setIsOpen(false);
        localStorage.setItem('seen_welcome_modal', 'true');
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => {
            if (!open) handleClose();
        }}>
            <DialogContent className="sm:max-w-md border-0 shadow-2xl overflow-hidden p-0 gap-0">
                {/* Header med Gradient Bakgrund */}
                <div className="bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 p-6 text-center text-white relative overflow-hidden">
                    {/* Dekorativa cirklar */}
                    <div className="absolute top-[-20%] left-[-10%] w-32 h-32 bg-white/10 rounded-full blur-2xl pointer-events-none"></div>
                    <div className="absolute bottom-[-20%] right-[-10%] w-32 h-32 bg-yellow-300/20 rounded-full blur-2xl pointer-events-none"></div>

                    <div className="relative z-10 transform translate-y-2">
                        <div className="mx-auto mb-3 w-16 h-16 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center shadow-lg text-4xl transform -rotate-3 hover:rotate-3 transition-transform duration-500">
                            👋
                        </div>
                        <DialogTitle className="text-2xl font-black tracking-tight mb-1 drop-shadow-sm">
                            Välkommen till VADKUL
                        </DialogTitle>
                        <p className="text-white/90 font-medium text-sm">
                            Din lokala guide till roliga händelser
                        </p>
                    </div>
                </div>

                <div className="p-6 space-y-6 bg-white">
                    <div className="grid gap-4">
                        <div className="flex items-start gap-4 group">
                            <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl shrink-0 group-hover:scale-110 transition-transform duration-300">
                                <Map size={24} strokeWidth={2.5} />
                            </div>
                            <div>
                                <h4 className="font-bold text-slate-800">Utforska kartan</h4>
                                <p className="text-sm text-slate-500 leading-snug">Se vad som händer nära dig just nu. Hitta dolda pärlor!</p>
                            </div>
                        </div>

                        <div className="flex items-start gap-4 group">
                            <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl shrink-0 group-hover:scale-110 transition-transform duration-300">
                                <Calendar size={24} strokeWidth={2.5} />
                            </div>
                            <div>
                                <h4 className="font-bold text-slate-800">Skapa egna events</h4>
                                <p className="text-sm text-slate-500 leading-snug">Bjud in vänner eller gör det öppet för alla. Du bestämmer!</p>
                            </div>
                        </div>

                        <div className="flex items-start gap-4 group">
                            <div className="p-3 bg-pink-50 text-pink-600 rounded-2xl shrink-0 group-hover:scale-110 transition-transform duration-300">
                                <Rocket size={24} strokeWidth={2.5} />
                            </div>
                            <div>
                                <h4 className="font-bold text-slate-800">Häng på direkt</h4>
                                <p className="text-sm text-slate-500 leading-snug">Ingen anmälan krävs på öppna events. Bara dyk upp och ha kul.</p>
                            </div>
                        </div>
                    </div>

                    <Button
                        onClick={handleClose}
                        className="w-full py-6 text-lg font-bold rounded-xl bg-slate-900 text-white hover:bg-slate-800 hover:scale-[1.02] transition-all duration-200 shadow-xl shadow-slate-200"
                    >
                        Nu kör vi! 🚀
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}
