import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { AppEvent } from '../../types';
import { formatEventDate } from '../../utils/dateUtils';
import { calculateDistance, loadLocationFromLocalStorage } from '../../utils/mapUtils';
import { EVENT_CATEGORIES, type EventCategoryType } from '../../utils/categories';
import { MapPin, CheckCircle2, Star, Clock, ArrowRight } from 'lucide-react';
import { useMemo, useState, useEffect } from 'react';

import { useAuth } from '../../context/AuthContext';
import { Card, CardContent, CardFooter } from '@/components/ui/card';

interface EventCardProps {
    event: AppEvent;
    compact?: boolean;
}

export default function EventCard({ event, compact = false }: EventCardProps) {
    const router = useRouter();
    const { user } = useAuth();

    // --- DATA ---
    const category = EVENT_CATEGORIES[event.type as EventCategoryType] || EVENT_CATEGORIES.other;
    const emoji = category.emoji;

    // Bild-logik (prioritera eventets bild, annars kategori-default)
    const rawCoverImage = event.coverImage || category.defaultImage;
    const coverImage = typeof rawCoverImage === 'string' ? rawCoverImage : rawCoverImage.src;

    // --- DISTANS BERÄKNING (NYTT) ---
    const [distance, setDistance] = useState<number | null>(
        typeof event.location.distance === 'number' ? event.location.distance : null
    );

    useEffect(() => {
        if (typeof event.location.distance === 'number') {
            setDistance(event.location.distance);
            return;
        }

        // Fallback: Räkna ut från localStorage
        const userLoc = loadLocationFromLocalStorage();
        if (userLoc && event.lat && event.lng) {
            setDistance(calculateDistance(userLoc.lat, userLoc.lng, event.lat, event.lng));
        }
    }, [event.lat, event.lng, event.location.distance]);

    const formatDistance = (d: number) => {
        if (d < 1) return `${Math.round(d * 1000)} m`;
        return `${d.toFixed(1)} km`;
    };

    // --- STATUS LOGIK ---
    const currentCount = event.attendees.length;
    const spotsLeft = event.maxParticipants - currentCount;
    const isFull = currentCount >= event.maxParticipants;
    const isGuaranteed = currentCount >= event.minParticipants;

    // --- DELTAGAR LOGIK ---
    const visibleAttendees = event.attendees.slice(0, 3);
    const hiddenCount = event.attendees.length - visibleAttendees.length;

    // --- LOADING STATE ---
    const [imageLoaded, setImageLoaded] = useState(false);

    return (
        <Link href={`/event/${event.id}`} className="block h-full group">
            <Card className="h-full flex flex-col overflow-hidden transition-all duration-300 hover:shadow-lg hover:-translate-y-1 border-border/50 bg-card/80 backdrop-blur-sm">

                {/* --- OMSLAGSBILD (Header del av kortet, men custom content) --- */}
                <div className={`relative w-full bg-muted overflow-hidden ${compact ? 'h-24' : 'h-32'}`}>
                    {/* Skeleton Pulse while loading */}
                    {!imageLoaded && (
                        <div className="absolute inset-0 bg-muted animate-pulse z-10" />
                    )}

                    <img
                        src={coverImage}
                        alt={event.title}
                        loading="lazy"
                        decoding="async"
                        onLoad={() => setImageLoaded(true)}
                        className={`w-full h-full object-cover transition-transform duration-700 ease-in-out group-hover:scale-105 ${imageLoaded ? 'opacity-100' : 'opacity-0'}`}
                    />

                    {/* Gradient Overlay */}
                    <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/60 to-transparent opacity-60"></div>

                    {/* Badge Top Left */}
                    <div className="absolute top-2 left-2 px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wide flex items-center gap-1.5 shadow-sm bg-background/90 text-foreground/90 backdrop-blur-sm">
                        <span>{emoji}</span>
                        {category.label}
                    </div>

                    {/* Date Badge Bottom Right */}
                    <div className="absolute bottom-2 right-2 bg-background/90 backdrop-blur-md text-foreground font-bold px-2 py-1 rounded-md text-xs shadow-sm flex flex-col items-center leading-none">
                        <span className="text-[10px] uppercase text-destructive tracking-wider">{event.time.toLocaleDateString('sv-SE', { month: 'short' }).replace('.', '')}</span>
                        <span className="text-lg">{event.time.getDate()}</span>
                    </div>
                </div>

                <CardContent className={`flex-1 flex flex-col ${compact ? 'p-3' : 'p-4'} pt-3`}>
                    <h3 className={`font-bold leading-tight mb-3 group-hover:text-primary transition-colors line-clamp-2 ${compact ? 'text-sm' : 'text-base'}`}>
                        {event.title}
                    </h3>

                    <div className="space-y-2 mb-4 text-xs font-medium text-muted-foreground mt-auto">
                        <div className="flex items-center gap-2">
                            <Clock size={14} className="text-muted-foreground/70" />
                            <span>{formatEventDate(event.time)}</span>
                        </div>

                        <div className="flex items-start gap-2">
                            <MapPin size={14} className="text-muted-foreground/70 mt-0.5" />
                            <div className="flex flex-col min-w-0">
                                <div className="flex items-center gap-1">
                                    <span className="truncate">{event.location.name}</span>
                                </div>
                                {distance !== null && (
                                    <span className="text-[10px] text-muted-foreground/60 font-normal">
                                        {formatDistance(distance)} bort
                                    </span>
                                )}
                            </div>

                            {/* Status Badges - Moved to right */}
                            <div className="ml-auto pl-2 shrink-0">
                                {isGuaranteed ? (
                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold text-emerald-600 bg-emerald-100 dark:bg-emerald-900/30 dark:text-emerald-400 px-1.5 py-0.5 rounded shadow-sm border border-emerald-200/50">
                                        <CheckCircle2 size={10} /> Blir av!
                                    </span>
                                ) : spotsLeft > 0 && (
                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold text-amber-600 bg-amber-100 dark:bg-amber-900/30 dark:text-amber-400 px-1.5 py-0.5 rounded shadow-sm border border-amber-200/50">
                                        <Clock size={10} /> {event.minParticipants - currentCount} saknas
                                    </span>
                                )}
                            </div>
                        </div>
                    </div>
                </CardContent>

                <CardFooter className={`border-t border-border/50 pt-3 flex items-end justify-between ${compact ? 'p-3' : 'p-4'}`}>
                    {/* VÄNSTER: Värd Info */}
                    <div className="flex items-center gap-2 group/host"
                        onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            if (event.host.uid && user?.uid !== event.host.uid) {
                                router.push(`/public-profile/${event.host.uid}`);
                            } else if (event.host.uid) {
                                router.push('/profile');
                            }
                        }}
                    >
                        {event.host.photoURL ? (
                            <img src={event.host.photoURL} alt={event.host.name} className="w-6 h-6 rounded-full object-cover ring-1 ring-border" />
                        ) : (
                            <div className="w-6 h-6 rounded-full bg-muted flex items-center justify-center text-[9px] font-bold text-muted-foreground">
                                {event.host.initials}
                            </div>
                        )}
                        <div className="flex flex-col leading-none">
                            <span className="text-[10px] font-semibold group-hover/host:text-primary transition-colors cursor-pointer">
                                {event.host.name.split(' ')[0]}
                            </span>
                            <div className="flex items-center text-[9px] text-amber-500">
                                <Star size={8} fill="currentColor" className="mr-0.5" />
                                {event.host.rating.toFixed(1)}
                            </div>
                        </div>
                    </div>

                    {/* HÖGER: Deltagare */}
                    <div className="flex -space-x-1.5 pl-2">
                        {visibleAttendees.map((attendee, i) => (
                            <div key={i} className="relative z-10 hover:z-20 transition-transform hover:scale-110">
                                {attendee.photoURL ? (
                                    <img src={attendee.photoURL} className="w-5 h-5 rounded-full object-cover ring-2 ring-card" title={attendee.displayName} />
                                ) : (
                                    <div className="w-5 h-5 rounded-full bg-muted ring-2 ring-card flex items-center justify-center text-[8px] font-bold text-muted-foreground">
                                        {attendee.displayName?.charAt(0) || '?'}
                                    </div>
                                )}
                            </div>
                        ))}
                        {hiddenCount > 0 && (
                            <div className="w-5 h-5 rounded-full bg-muted ring-2 ring-card flex items-center justify-center text-[8px] font-bold text-muted-foreground z-0">
                                +{hiddenCount}
                            </div>
                        )}
                        {/* Hover Arrow Effect in this region */}
                        <ArrowRight size={16} className="text-primary opacity-0 -translate-x-2 group-hover:translate-x-0 group-hover:opacity-100 transition-all absolute right-4 bottom-[18px]" />
                    </div>
                </CardFooter>

            </Card>
        </Link>
    );
}